#!/usr/bin/env python3
"""Generate the Cloud Infra Playbook paid guide and public sample."""
from __future__ import annotations
import argparse, importlib.util
from pathlib import Path
from reportlab.lib.pagesizes import A4
from reportlab.lib.units import mm
from reportlab.platypus import BaseDocTemplate, Frame, PageTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle
from reportlab.platypus.tableofcontents import TableOfContents

base_path=Path(__file__).with_name('generate-typescript-systems-blueprint.py')
spec=importlib.util.spec_from_file_location('dv_pdf_base',base_path);base=importlib.util.module_from_spec(spec);spec.loader.exec_module(base)

def t(title, explanation, operations, failures, exercise, diagram, code):
 return (title,explanation,operations,failures,exercise,diagram,code)

TOPICS=[
t('Cloud Infrastructure Fundamentals','Cloud infrastructure combines compute, network, identity, storage, deployment, and observability into an operated system. Managed services shift responsibilities but never remove ownership. Begin with workload, data sensitivity, recovery objectives, latency, scale, team capability, and budget—not a provider diagram. Every component needs an owner, failure policy, and evidence that it meets its objective.','Define workload and data classification; document service-level objectives; assign operational ownership; choose the simplest managed boundary; test failure and recovery before launch.','Treating cloud adoption as automatic reliability; selecting services before requirements; omitting ownership and deletion paths; assuming provider availability equals application availability.','Write a one-page operating model for a small API: consumers, dependencies, SLO, data class, owner, escalation, recovery target, and monthly budget guardrail.',['REQUIREMENTS','CONTROL PLANE','DATA PLANE','OPERATIONS'],"# Conceptual inventory\nservice: student-api\nowner: platform-team\ndata_class: confidential\nrto_minutes: 60\nrpo_minutes: 15"),
t('Regions, Availability Zones, and Fault Domains','A region is a geographic provider area; availability zones are separately operated locations within it. Multi-zone design reduces a class of facility failures but does not protect against application defects, bad deployments, account compromise, or regional dependencies. Multi-region adds replication, consistency, routing, testing, and cost complexity.','Map every dependency to a fault domain; deploy redundant stateless capacity across zones; keep backups outside the primary failure boundary; document regional failover authority; test degraded modes.','Calling two instances highly available when both share one zone; synchronous cross-region coupling without latency review; untested DNS failover; confusing backups with live replicas.','Draw a two-zone service and list failures it survives and failures it does not. Expected outcome: explicit database, NAT, load-balancer, and operator dependencies.',['REGION','ZONE A','ZONE B','SHARED SERVICES','RECOVERY'],"# Conceptual objective, not an AWS deployment\nprimary_region: ap-south-1\nrecovery_region: ap-southeast-1\nregional_failover: manual-approved"),
t('Stateless Application Architecture','A stateless instance keeps no irreplaceable session or uploaded file on local disk. Requests can reach any healthy instance because durable state lives in controlled stores. Statelessness improves replacement and scaling, but databases, caches, queues, and object storage still carry state and require availability and recovery design.','Store sessions in signed tokens or a shared server store; send uploads directly to durable private storage; make requests idempotent where clients retry; drain connections before termination; never depend on local ephemeral files.','Saving paid files on ephemeral instance disks; using process memory as authoritative session state; scaling non-idempotent workers; terminating before requests drain.','Refactor a local-disk upload service into stateless application nodes plus private object storage and metadata.',['CLIENT','LOAD BALANCER','STATELESS APP','DURABLE STORES'],"GET /health/ready HTTP/1.1\nHost: service.internal\n# Expected 200 only when this instance can safely receive traffic."),
t('Compute: VMs, Containers, and Serverless','Virtual machines expose an operating system boundary and suit custom agents or steady workloads. Containers package processes consistently but still need image security, scheduling, networking, and persistent-state design. Serverless reduces server management and can scale to zero, while introducing runtime limits, cold starts, provider coupling, and event retry semantics.','Compare workload duration and concurrency; estimate steady and burst cost; define patch responsibility; verify runtime and network constraints; choose based on team operations capability.','Calling containers a security boundary by default; placing databases inside disposable containers without persistence; ignoring serverless retry duplication; running oversized always-on VMs.','Score VM, container, and serverless options for a web API and nightly report using cost, latency, portability, and operations effort.',['WORKLOAD','VM','CONTAINER','SERVERLESS','DECISION'],"# Illustrative container health configuration\nhealthcheck:\n  path: /health/ready\n  interval_seconds: 15\n  timeout_seconds: 3"),
t('Networking, DNS, HTTPS, and Reverse Proxies','DNS maps names to endpoints but caches according to TTL and does not provide instantaneous failover. HTTPS authenticates endpoints and protects traffic in transit when certificates and hostname validation are correct. Reverse proxies terminate TLS, route requests, enforce limits, and forward identity context only through trusted headers.','Automate certificate renewal; redirect HTTP carefully; set proxy timeouts and body limits; trust forwarded headers only from known proxies; monitor DNS and certificate expiry.','Publicly exposing application ports behind the proxy; trusting arbitrary X-Forwarded-For; setting infinite timeouts; assuming low DNS TTL guarantees fast failover.','Trace a request from DNS resolution through TLS, proxy, application, and dependency, naming each timeout and log correlation point.',['DNS','TLS','REVERSE PROXY','APP','DEPENDENCY'],"# Illustrative reverse-proxy policy\nrequest_timeout_seconds: 30\nmax_body_mb: 10\nforwarded_headers_from: trusted_load_balancer_only"),
t('VPCs, Subnets, Routing, and Security Groups','A VPC is an isolated logical network. Public subnets route toward an internet gateway; private subnets do not accept direct inbound internet routes. Route tables control paths, while security groups filter allowed flows. NAT provides outbound connectivity and can become a cost and availability dependency.','Start from required flows; place public entry points separately from private workloads; restrict ingress and egress; use private service endpoints where justified; retain flow logs with a privacy policy.','Calling a subnet private while assigning public addresses; allowing 0.0.0.0/0 to databases; relying on obscurity instead of controls; forgetting NAT cost and resilience.','Produce a flow matrix for browser, load balancer, app, database, object storage, and administration.',['INTERNET','PUBLIC SUBNET','PRIVATE APP','PRIVATE DATA'],"# Conceptual flow rule\nsource: app-security-group\ndestination: database-security-group\nprotocol: tcp\nport: 5432\naction: allow"),
t('Environment Separation: Development, Staging, Production','Environment separation limits blast radius and prevents test activity from changing production. Strong separation uses distinct credentials, data, networks, and preferably accounts or projects. Staging is useful only when it resembles relevant production behavior without copying uncontrolled customer data.','Use separate identities and secrets; prevent production writes from lower environments; sanitize test data; promote immutable artifacts; document emergency production access.','One shared database with environment prefixes; copying customer data into laptops; rebuilding artifacts between staging and production; permanent broad developer access.','Design DEV, STAGING, and PROD boundaries and state exactly what is shared: source, artifact, schema migration, and observability definitions.',['SOURCE','BUILD ONCE','STAGING','APPROVAL','PRODUCTION'],"APP_ENV=staging\nLOG_LEVEL=info\n# Illustrative only. Secrets are injected separately."),
t('Configuration and Secrets Management','Configuration selects behavior; secrets grant access. Validate both at startup, but store secrets in a managed server-side secret facility rather than source, images, client bundles, or ordinary logs. Rotation requires consumers that can reload or redeploy safely and an overlap plan when providers support multiple credentials.','Fail closed on missing configuration; separate public and private values; scope secret access per workload; rotate and revoke; audit reads without recording secret contents.','NEXT_PUBLIC secrets; credentials in container layers; secrets in exception messages; rotation plans that require downtime without rehearsal.','Run the included local environment validator, then design a zero-downtime credential rotation sequence.',['CONFIG SOURCE','VALIDATE','WORKLOAD ID','SECRET STORE'],"APP_ENV=production PORT=3000 LOG_LEVEL=info \\\n  bash cloud-infra-playbook-examples.sh validate\n# Expected: configuration:valid"),
t('Identity, Access Control, and Least Privilege','Human and workload identities require separate policies. Least privilege grants only necessary actions on named resources for a bounded purpose. Short-lived credentials reduce exposure, but policy mistakes and session theft remain risks. High-impact changes need stronger authentication and auditable approval.','Prefer workload identity over static keys; separate deploy and runtime roles; require MFA for humans; review unused permissions; centralize audit events.','Wildcard administrator policies; shared human accounts; long-lived access keys; authorizing only in user interfaces.','Write minimal read and write permissions for an application that reads one secret and writes one object prefix.',['IDENTITY','AUTHENTICATE','POLICY','RESOURCE','AUDIT'],"# AWS-oriented IAM idea; illustrative, not deployed\nAction: s3:PutObject\nResource: arn:aws:s3:::example-private/product/*\nEffect: Allow"),
t('Storage, Object Storage, and Databases','Block storage attaches to compute, object storage stores immutable-like blobs by key, and databases provide query and consistency models. Choose from access pattern, durability, latency, concurrency, transaction, retention, and cost requirements. Encryption does not replace authorization or backups.','Keep private objects non-public; use lifecycle and retention deliberately; enforce database constraints; plan connection limits; test migrations on representative data.','Serving paid files from public buckets; treating object listings as transactions; running schema changes without rollback analysis; ignoring connection exhaustion.','Select storage for private PDFs, application records, logs, and cache entries, explaining access and recovery.',['APPLICATION','OBJECTS','DATABASE','CACHE','BACKUP'],"{\"objectKey\":\"product/version/file.pdf\",\"visibility\":\"private\",\"retentionDays\":365}"),
t('Backups, Restoration, and Recovery Planning','A backup is useful only if it is complete, protected, retained, and restorable within objectives. RPO limits acceptable data loss; RTO limits recovery time. Replicas can copy corruption and therefore do not replace independent backups. Restoration tests need representative scale and documented evidence.','Define RPO and RTO per dataset; encrypt and separate backup access; verify checksums; perform scheduled restore tests; record dependencies and decision authority.','Counting snapshots without restoration; storing backups in the same failure boundary; never testing credentials; promising zero loss without architecture evidence.','Complete the backup worksheet: source, schedule, retention, encryption, location, owner, last restore result, measured RTO, and measured RPO.',['DATA','BACKUP','VERIFY','RESTORE TEST','EVIDENCE'],"bash cloud-infra-playbook-examples.sh manifest backup-42 sha256:test\n# Emits valid JSON with restoreTested=false."),
t('CI/CD Pipelines','A delivery pipeline converts reviewed source into a traceable immutable artifact, tests it, scans dependencies, promotes the same artifact, records approvals, and deploys with observable gates. The pipeline itself is privileged infrastructure and must protect tokens and logs.','Pin trusted actions; use short-lived deployment identity; generate provenance and artifact digests; separate build from deploy; keep rollback artifacts.','Rebuilding during production deploy; secrets in pipeline output; unreviewed mutable action tags; deployments with no owner.','Design stages from commit through rollback, including failure gates and evidence retained at each step.',['COMMIT','TEST','BUILD','SCAN','PROMOTE','DEPLOY'],"# Illustrative pipeline sequence\nsteps: [lint, typecheck, test, build, scan, deploy-staging, verify, approve, deploy-production]"),
t('Rolling, Blue/Green, and Canary Deployments','Rolling replaces capacity gradually and is economical but mixes versions. Blue/green prepares a complete parallel environment and switches traffic, requiring duplicate capacity and data compatibility. Canary exposes a small traffic share and needs reliable metrics plus automatic or explicit rollback criteria.','Keep database changes backward compatible; define promotion metrics; separate deploy from release where useful; rehearse rollback; account for long-lived connections.','Calling a canary safe without representative traffic; rollback code against incompatible schema; destroying blue immediately; ignoring background workers.','Choose a strategy for an API with schema migration and define capacity, health gates, observation window, and rollback trigger.',['ARTIFACT','SMALL EXPOSURE','MEASURE','PROMOTE/ROLLBACK'],"bash cloud-infra-playbook-examples.sh decide 1 220\n# Expected: continue\nbash cloud-infra-playbook-examples.sh decide 3 220\n# Expected: rollback"),
t('Health Checks, Readiness, and Rollback','Liveness asks whether a process should be restarted; readiness asks whether it can safely receive traffic. Startup probes protect slow initialization. Checks should be fast, bounded, and meaningful without creating dependency storms. Rollback must restore compatible code and configuration while preserving data integrity.','Separate liveness and readiness; use short timeouts; remove readiness before draining; monitor deployment-specific indicators; define rollback authority.','A health endpoint that always returns 200; querying every dependency on every probe; restarting for downstream outage; rollback with incompatible migrations.','Write liveness, readiness, and startup conditions for an API plus a rollback decision table.',['STARTUP','LIVENESS','READINESS','TRAFFIC','DRAIN'],"GET /health/live  -> process loop responsive\nGET /health/ready -> required local initialization complete\n# Conceptual responses, not a running endpoint."),
t('Logs, Metrics, Traces, and Alerting','Logs describe events, metrics summarize time-series behavior, and traces connect work across boundaries. Observability begins with questions and service objectives, not data volume. Correlation IDs help without becoming authentication tokens. Telemetry can contain sensitive data and needs access and retention controls.','Use structured safe logs; measure rate, errors, duration, and saturation; sample traces deliberately; alert on user impact; attach owners and runbooks.','Logging tokens or payloads; paging on every warning; averages hiding tail latency; high-cardinality identifiers in metric labels.','Define a dashboard and three actionable alerts for a checkout API, including thresholds, owner, and first diagnostic query.',['REQUEST','LOG/METRIC/TRACE','SLO','ALERT','RUNBOOK'],"{\"level\":\"error\",\"event\":\"checkout_failed\",\"requestId\":\"safe-correlation-id\"}"),
t('Error Budgets, Incident Response, and Runbooks','An SLO defines a measured reliability objective; its error budget is the allowed unreliability over a window. Budgets guide risk decisions but require trustworthy indicators. Incident response prioritizes safety, impact reduction, communication, evidence preservation, and recovery.','Name incident roles; record a timeline; stabilize before deep diagnosis; communicate confirmed facts; hold blameless corrective review.','Inventing an SLO without measurement; changing multiple systems during incident response; deleting evidence; declaring resolution before data reconciliation.','Write a runbook for elevated 5xx errors with detection, triage, rollback, communication, verification, and follow-up.',['DETECT','DECLARE','MITIGATE','RECOVER','REVIEW'],"SEV-2 RUNBOOK\n1. Confirm impact and scope\n2. Freeze unrelated changes\n3. Mitigate or rollback\n4. Verify service and data\n5. Record follow-up owners"),
t('Scaling, Availability, and Performance','Horizontal scaling adds instances; vertical scaling adds resources. Both are bounded by databases, locks, queues, external quotas, and shared state. Autoscaling reacts after a signal and must account for startup time. Performance optimization starts with measurement and load shape.','Define capacity units; load-test representative paths; set concurrency limits; protect dependencies with backpressure; review database and cache behavior.','Scaling application nodes while exhausting database connections; CPU-only autoscaling for queue work; unlimited retries; caching without invalidation.','Estimate capacity for steady and burst traffic, then identify the first three bottlenecks and protective limits.',['DEMAND','QUEUE','CAPACITY','BOTTLENECK','SCALE'],"# Conceptual capacity worksheet\nrequests_per_second: 120\np95_target_ms: 300\nmax_db_connections: 80\nheadroom_percent: 30"),
t('Infrastructure as Code Fundamentals','Infrastructure as Code makes desired configuration reviewable and repeatable. State maps configuration to real resources and must be protected. Plans need human interpretation; drift detection reveals out-of-band change but should not automatically destroy unknown production state.','Pin providers and modules; protect state and locking; review plans; separate environment state; test modules and policy checks.','Committing secrets in variables; one global state for every environment; automatic apply from untrusted branches; destructive changes without backup.','Review an illustrative network plan and identify replacement, deletion, public exposure, and cost changes before approval.',['CODE','VALIDATE','PLAN','APPROVE','APPLY','DRIFT'],"# Illustrative Terraform; syntax not validated because Terraform is absent\nresource \"aws_s3_bucket\" \"private_assets\" {\n  bucket = var.private_bucket_name\n}"),
t('Security Hardening and Dependency Management','Hardening removes unnecessary exposure, patches supported components, restricts execution, protects supply chains, and creates useful detection. Vulnerability severity needs reachability and business context. Dependency updates require provenance, testing, and rollback rather than blind automation.','Use minimal supported images; run non-root where feasible; generate an SBOM; pin and scan dependencies; patch through tested delivery.','Exposing management ports; privileged containers by default; ignoring transitive dependencies; delaying critical patches without compensating controls.','Create a monthly hardening review covering identities, network exposure, images, dependencies, secrets, logs, and restoration.',['INVENTORY','HARDEN','SCAN','PATCH','VERIFY'],"# Illustrative container controls\nrunAsNonRoot: true\nreadOnlyRootFilesystem: true\nallowPrivilegeEscalation: false"),
t('Cloud Cost Awareness and Operational Budgeting','Cloud cost follows provisioned capacity, usage, data transfer, requests, retention, licenses, and support. Optimization must preserve reliability and security. Unit economics—cost per customer, request, or pipeline run—often guides decisions better than a single monthly total.','Tag owner and environment; set budgets and anomaly alerts; review idle capacity; model data transfer and retention; record reliability tradeoffs.','Inventing future prices; deleting backups to meet budget; ignoring NAT and egress; buying commitments before measuring stable demand.','Build a budget worksheet with compute, database, storage, transfer, telemetry, backup, support, headroom, and owner.',['USAGE','RATE CARD','FORECAST','BUDGET','REVIEW'],"# Values intentionally omitted: obtain current provider pricing.\nmonthly_cost = sum(usage_quantity * current_unit_rate)"),
t('AWS-Oriented Architecture Examples','An AWS-oriented web design may use Route 53, CloudFront, an Application Load Balancer, compute across multiple Availability Zones, RDS, S3, CloudWatch, IAM roles, KMS, and Secrets Manager. These are architectural examples, not deployed resources or universal recommendations. Service behavior and pricing must be verified against current AWS documentation.','Map shared and zonal services; use workload IAM roles; keep S3 assets private; place RDS in private subnets; test backup and regional recovery.','Claiming multi-region from multi-zone RDS; public S3 paid assets; wildcard IAM; assuming managed means maintenance-free.','Draw an AWS-oriented SaaS architecture and label public entry, private compute, data, identities, logs, backups, and failure boundaries.',['ROUTE53/CDN','ALB','APP AZs','RDS/S3','CLOUDWATCH'],"# Illustrative AWS service map; no resources deployed\ndns: Route53\nedge: CloudFront\ncompute: ECS_or_Lambda\ndata: RDS_and_private_S3"),
t('Production Deployment Checklists','A production checklist is evidence that prerequisites were satisfied, not a substitute for judgment. It covers ownership, contracts, capacity, security, migration, recovery, monitoring, communication, and rollback. Each item should name evidence and an accountable approver.','Verify immutable artifact digest; confirm migrations and backup; validate secrets and permissions; review dashboards and alerts; rehearse rollback and communication.','Checkboxes with no evidence; first restore test after launch; missing dependency owners; approving one version and deploying another.','Complete the included launch worksheet and attach evidence for every critical item.',['READINESS','APPROVAL','DEPLOY','VERIFY','HANDOFF'],"PRE-DEPLOY\n[ ] artifact digest recorded\n[ ] backup and restore evidence current\n[ ] rollback owner present\n[ ] alert routing verified"),
t('Incident Investigation Examples','Investigation separates symptoms, scope, timeline, recent changes, dependencies, and data correctness. A latency incident may arise from connection exhaustion, downstream slowdown, lock contention, or resource saturation. A deployment incident requires comparing versions and configuration. A data incident requires reconciliation before reopening publication.','Capture timestamps in one timezone; preserve logs and deploy metadata; form testable hypotheses; change one variable at a time; verify user and data recovery.','Jumping to root cause; querying production destructively; changing many controls simultaneously; closing after graphs recover without data checks.','Investigate a p95 latency spike after deployment using timeline, saturation, database connections, traces, rollback, and validation.',['SYMPTOM','SCOPE','TIMELINE','HYPOTHESIS','EVIDENCE','FIX'],"INCIDENT NOTES\nimpact: checkout p95 > 2s\nrecent_change: release-2026-10-25\nfirst_checks: error_rate, db_pool, downstream_latency"),
t('Practical Architecture Case Studies','Case one runs a stateless SaaS API across two zones with private database access, immutable deployment, and tested rollback. Case two delivers paid PDFs from private object storage after server-side entitlement checks. Case three processes a nightly data pipeline with checkpoints, rejection handling, reconciliation, and recovery evidence.','Declare trust boundaries; map every stateful dependency; define SLO and capacity; design deployment and rollback; include backup and incident paths.','Happy-path-only diagrams; public paid files; payment state from redirects; checkpoints advanced before successful commit.','Produce a complete architecture review for one case, including threat, cost, failure, deployment, observability, and recovery sections.',['CLIENT','EDGE','APP','DATA','OPERATIONS'],"CASE REVIEW\n1. requirements and constraints\n2. trust and fault boundaries\n3. delivery and rollback\n4. observability and incident response\n5. cost and recovery evidence"),
t('Interview Questions and Revision Material','Strong infrastructure answers begin with requirements: users, traffic, data class, latency, availability, recovery, team, and budget. Explain tradeoffs among compute models, zones and regions, network boundaries, deployment strategies, observability, IaC, security, and cost. State what is conceptual versus verified.','Clarify scale and SLO; draw trust and fault boundaries; identify state; explain failure and recovery; quantify assumptions without inventing guarantees.','Listing services without decisions; ignoring data recovery; equating autoscaling with availability; giving current-price claims from memory.','Answer: design a resilient private digital-download service and explain authentication, entitlement, storage, scaling, monitoring, backup, and cost.',['QUESTION','REQUIREMENTS','DESIGN','FAILURES','TRADEOFFS'],"REVISION\nidentity before authorization\nreadiness before traffic\nbackup plus restore evidence\nmetrics plus owned runbook\nimmutable artifact plus rollback"),
]

class CloudDoc(BaseDocTemplate):
 def __init__(self,filename,**kw):super().__init__(filename,**kw);self.addPageTemplates(PageTemplate(id='main',frames=Frame(self.leftMargin,self.bottomMargin,self.width,self.height,id='f'),onPage=self.art))
 def art(self,c,doc):
  c.saveState();c.setFillColor(base.BG);c.rect(0,0,A4[0],A4[1],fill=1,stroke=0);c.setStrokeColor(base.BORDER);c.line(20*mm,15*mm,A4[0]-20*mm,15*mm);c.setFillColor(base.MUTED);c.setFont('Helvetica',8);c.drawString(20*mm,9*mm,'DevVault  |  Cloud Infra Playbook');c.drawRightString(A4[0]-20*mm,9*mm,str(doc.page));c.restoreState()
 def afterFlowable(self,f):
  if isinstance(f,Paragraph) and f.style.name in ('Chapter','H2'):
   level=0 if f.style.name=='Chapter' else 1;text=f.getPlainText();key=f'h{level}-{self.seq.nextf("h")}';self.canv.bookmarkPage(key);self.canv.addOutlineEntry(text,key,level=level,closed=False);self.notify('TOCEntry',(level,text,self.page,key))

def cover(s,sample):
 label='PUBLIC SAMPLE' if sample else 'PROFESSIONAL OPERATIONS GUIDE';return [Spacer(1,27*mm),Paragraph('CLOUD INFRA<br/>PLAYBOOK',s['title']),Paragraph('Resilient architecture, secure delivery, observability, recovery, and operational decision-making',s['sub']),Spacer(1,10*mm),Table([[label],['DevVault Educational Series'],['Twenty-five practical infrastructure chapters and operational worksheets'],['Edition 1.0  |  October 2026']],colWidths=[160*mm],style=TableStyle([('BACKGROUND',(0,0),(-1,0),base.VIOLET),('BACKGROUND',(0,1),(-1,-1),base.PLUM),('TEXTCOLOR',(0,0),(-1,-1),base.IVORY),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('BOX',(0,0),(-1,-1),1,base.BORDER),('INNERGRID',(0,0),(-1,-1),.25,base.BORDER),('LEFTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8)])),Spacer(1,10*mm),Paragraph('Original educational material. Local Bash and JSON examples are tested. AWS, Terraform, container, proxy, and managed-service configurations are explicitly illustrative and were not deployed by this generator.',s['small']),PageBreak()]

def worksheet(title,body,s):return [Paragraph(title,s['chapter']),Paragraph(body,s['body']),Table([['Decision / evidence','Owner','Status'],['Requirements and assumptions','',''],['Security and privacy','',''],['Failure and rollback','',''],['Recovery evidence','',''],['Cost guardrail','','']],colWidths=[90*mm,35*mm,35*mm],rowHeights=[10*mm]*6,style=TableStyle([('BACKGROUND',(0,0),(-1,0),base.VIOLET),('BACKGROUND',(0,1),(-1,-1),base.PLUM),('TEXTCOLOR',(0,0),(-1,-1),base.IVORY),('GRID',(0,0),(-1,-1),.5,base.BORDER),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5)])),PageBreak()]

def build(path,sample=False):
 s=base.styles();story=cover(s,sample)
 if sample:
  story += [Paragraph('What this sample includes',s['chapter']),Paragraph('This limited sample contains the first three foundational chapters. It demonstrates the full guide’s diagrams, operational recommendations, failure modes, configuration examples, and exercises without exposing deployment, security, recovery, incident, cost, AWS, and case-study chapters.',s['body']),PageBreak()]
  for i,item in enumerate(TOPICS[:3],1):story += base.chapter(item,i,s)
  story += [Paragraph('Continue with the complete playbook',s['chapter']),Paragraph('The complete guide continues through compute, networking, identity, storage, recovery, CI/CD, deployment, observability, incidents, scaling, IaC, hardening, cost, AWS-oriented examples, launch checklists, and case studies.',s['body'])]
 else:
  story += [Paragraph('Contents',s['chapter'])];toc=TableOfContents();toc.levelStyles=[s['toc0'],s['toc1']];story += [toc,PageBreak(),Paragraph('How to use this playbook',s['chapter']),Paragraph('Chapters 1–10 establish architecture and security boundaries. Chapters 11–20 cover recovery, delivery, observability, scaling, IaC, hardening, and cost. Chapters 21–25 apply the material to AWS-oriented examples, production reviews, incidents, case studies, and interviews. Examples marked illustrative require provider-specific validation before use.',s['body']),PageBreak()]
  for i,item in enumerate(TOPICS,1):
   story += base.chapter(item,i,s)
   if i==11:story += worksheet('Backup and Recovery Worksheet','Record the protected dataset, failure boundary, RPO, RTO, schedule, retention, encryption, checksum, restore environment, last measured recovery time, unresolved gaps, and accountable owner.',s)
   if i==16:story += worksheet('Incident Runbook Worksheet','Define detection source, severity, incident commander, communication channel, safe mitigation, rollback criteria, evidence preservation, recovery validation, and follow-up ownership.',s)
   if i==22:story += worksheet('Production Readiness Worksheet','Capture evidence for architecture, security, capacity, deployment, database migration, monitoring, backups, rollback, cost guardrails, on-call ownership, and approval.',s)
  story += [Paragraph('Final revision checklist',s['chapter']),Paragraph('Before launch: requirements and fault domains are explicit; identity and network access are least privilege; artifacts are immutable; secrets stay server-side; readiness gates traffic; deployment has measured rollback criteria; telemetry is safe and actionable; backups are restored in tests; incidents have owners; costs have budgets; and every cloud-specific claim is verified against current provider documentation.',s['body']),base.Flow(['REQUIRE','SECURE','DEPLOY','OBSERVE','RECOVER','REVIEW'])]
 doc=CloudDoc(str(path),pagesize=A4,leftMargin=20*mm,rightMargin=20*mm,topMargin=20*mm,bottomMargin=22*mm,title='Cloud Infra Playbook',author='DevVault',subject='Cloud infrastructure operations guide');doc.multiBuild(story)

def main():
 p=argparse.ArgumentParser();p.add_argument('--output-dir',type=Path,required=True);a=p.parse_args();a.output_dir.mkdir(parents=True,exist_ok=True);full=a.output_dir/'cloud-infra-playbook-study-guide-v1.pdf';sample=a.output_dir/'cloud-infra-playbook-public-sample-v1.pdf';build(full);build(sample,True);print({'full':str(full),'sample':str(sample),'chapters':len(TOPICS),'worksheets':3})
if __name__=='__main__':main()
